class MinStackPairs {
    vector<pair<int,int>> st;            // (value, min-so-far)
public:
    void push(int x) {
        int mn = st.empty() ? x : min(x, st.back().second);
        st.push_back({x, mn});
    }
    void pop() { st.pop_back(); }
    int top() const { return st.back().first; }
    int getMin() const { return st.back().second; }
};

// VERSION 2 -- delta encoding. Store 2*x - oldMin when a new minimum arrives;
// that encoded value is provably BELOW the new minimum, so it is recognisable.
// Recovery: oldMin = 2*curMin - encoded.
class MinStackDelta {
    vector<long long> st;
    long long curMin = 0;
public:
    void push(int x) {
        if (st.empty()) { st.push_back(x); curMin = x; return; }
        if (x < curMin) { st.push_back(2LL * x - curMin); curMin = x; }
        else            { st.push_back(x); }
    }
    void pop() {
        long long v = st.back(); st.pop_back();
        if (v < curMin) curMin = 2 * curMin - v;      // restore the previous minimum
    }
    int top() const {
        long long v = st.back();
        return (int)(v < curMin ? curMin : v);        // encoded slot hides the real value
    }
    int getMin() const { return (int)curMin; }
};

