class MinStackPairs:
    """VERSION 1 -- store the running minimum beside each value."""

    def __init__(self):
        self._st = []                    # (value, min-so-far)

    def push(self, x: int) -> None:
        mn = x if not self._st else min(x, self._st[-1][1])
        self._st.append((x, mn))

    def pop(self) -> None:
        self._st.pop()

    def top(self) -> int:
        return self._st[-1][0]

    def get_min(self) -> int:
        return self._st[-1][1]


class MinStackDelta:
    """VERSION 2 -- delta encoding. Store 2*x - old_min when a new minimum
    arrives; that encoded value is provably BELOW the new minimum, so it is
    recognisable. Recovery: old_min = 2*cur_min - encoded."""

    def __init__(self):
        self._st = []
        self._min = 0

    def push(self, x: int) -> None:
        if not self._st:
            self._st.append(x)
            self._min = x
            return
        if x < self._min:
            self._st.append(2 * x - self._min)
            self._min = x
        else:
            self._st.append(x)

    def pop(self) -> None:
        v = self._st.pop()
        if v < self._min:
            self._min = 2 * self._min - v    # restore the previous minimum

    def top(self) -> int:
        v = self._st[-1]
        return self._min if v < self._min else v   # encoded slot hides the real value

    def get_min(self) -> int:
        return self._min

