vector<int> nextGreaterElement(const vector<int>& nums1, const vector<int>& nums2) {
    unordered_map<int,int> nge;
    stack<int> st;                                     // decreasing bottom to top
    for (int x : nums2) {
        while (!st.empty() && st.top() < x) {          // x resolves everything smaller
            nge[st.top()] = x;
            st.pop();
        }
        st.push(x);
    }
    // anything still on the stack has no greater element to its right
    vector<int> out;
    out.reserve(nums1.size());
    for (int q : nums1) out.push_back(nge.count(q) ? nge[q] : -1);
    return out;
}

