vector<int> nextGreaterElements(const vector<int>& a) {
    int n = (int)a.size();
    vector<int> out(n, -1);
    stack<int> st;                                  // holds INDICES, decreasing by value
    for (int i = 0; i < 2 * n; ++i) {
        int idx = i % n;                            // virtual doubling, no extra array
        while (!st.empty() && a[st.top()] < a[idx]) {
            out[st.top()] = a[idx];
            st.pop();
        }
        if (i < n) st.push(idx);                    // only the FIRST lap pushes
    }
    return out;
}

