// O(1) SPACE: walk both from the right, skipping over deleted characters.
bool backspaceCompareO1(const string& a, const string& b) {
    int i = (int)a.size() - 1, j = (int)b.size() - 1;
    while (i >= 0 || j >= 0) {
        int skip = 0;
        while (i >= 0 && (a[i] == '#' || skip)) { skip += (a[i] == '#') ? 1 : -1; --i; }
        skip = 0;
        while (j >= 0 && (b[j] == '#' || skip)) { skip += (b[j] == '#') ? 1 : -1; --j; }
        if (i >= 0 && j >= 0) { if (a[i] != b[j]) return false; }
        else if (i >= 0 || j >= 0) return false;    // one ran out early
        --i; --j;
    }
    return true;
}

