def apply_backspaces(s: str) -> str:
    out = []
    for c in s:
        if c == "#":
            if out:
                out.pop()          # guard: # on an empty buffer is a no-op
        else:
            out.append(c)
    return "".join(out)


def backspace_compare(a: str, b: str) -> bool:
    return apply_backspaces(a) == apply_backspaces(b)


def backspace_compare_o1(a: str, b: str) -> bool:
    """O(1) SPACE: walk both from the right, skipping deleted characters."""
    i, j = len(a) - 1, len(b) - 1
    while i >= 0 or j >= 0:
        skip = 0
        while i >= 0 and (a[i] == "#" or skip):
            skip += 1 if a[i] == "#" else -1
            i -= 1
        skip = 0
        while j >= 0 and (b[j] == "#" or skip):
            skip += 1 if b[j] == "#" else -1
            j -= 1
        if i >= 0 and j >= 0:
            if a[i] != b[j]:
                return False
        elif i >= 0 or j >= 0:
            return False           # one ran out early
        i -= 1
        j -= 1
    return True

