    if (op == '*' || op == '/') return 2;
    if (op == '+' || op == '-') return 1;
    return 0;
}
bool rightAssoc(char op) { return op == '^'; }   // 2^3^2 is 2^(3^2), not (2^3)^2

string infixToPostfix(const string& s) {
    string out;
    stack<char> ops;
    for (char c : s) {
        if (isspace((unsigned char)c)) continue;
        if (isalnum((unsigned char)c)) { out += c; continue; }   // operand: emit now
        if (c == '(') { ops.push(c); continue; }
        if (c == ')') {
            while (!ops.empty() && ops.top() != '(') { out += ops.top(); ops.pop(); }
            if (!ops.empty()) ops.pop();                          // discard the '('
            continue;
        }
        // operator: pop everything that binds at least as tightly
        while (!ops.empty() && ops.top() != '(' &&
               (prec(ops.top()) > prec(c) ||
                (prec(ops.top()) == prec(c) && !rightAssoc(c)))) {
            out += ops.top(); ops.pop();
        }
        ops.push(c);
    }
    while (!ops.empty()) { out += ops.top(); ops.pop(); }
    return out;
}

