def prec(op: str) -> int:
    return {"^": 3, "*": 2, "/": 2, "+": 1, "-": 1}.get(op, 0)


def right_assoc(op: str) -> bool:
    return op == "^"        # 2^3^2 is 2^(3^2), not (2^3)^2


def infix_to_postfix(s: str) -> str:
    out, ops = [], []
    for c in s:
        if c.isspace():
            continue
        if c.isalnum():
            out.append(c)             # operand: emit now
        elif c == "(":
            ops.append(c)
        elif c == ")":
            while ops and ops[-1] != "(":
                out.append(ops.pop())
            if ops:
                ops.pop()             # discard the "("
        else:
            # operator: pop everything that binds at least as tightly
            while (ops and ops[-1] != "(" and
                   (prec(ops[-1]) > prec(c) or
                    (prec(ops[-1]) == prec(c) and not right_assoc(c)))):
                out.append(ops.pop())
            ops.append(c)
    while ops:
        out.append(ops.pop())
    return "".join(out)

