long long evalPostfix(const vector<string>& tokens) {
    stack<long long> st;
    for (const string& tk : tokens) {
        if (tk.size() > 1 || isdigit((unsigned char)tk[0])) {   // multi-digit or negative
            st.push(stoll(tk));
            continue;
        }
        long long b = st.top(); st.pop();      // RIGHT operand pops FIRST
        long long a = st.top(); st.pop();      // LEFT operand pops second
        switch (tk[0]) {
            case '+': st.push(a + b); break;
            case '-': st.push(a - b); break;   // a - b, NOT b - a
            case '*': st.push(a * b); break;
            case '/': st.push(a / b); break;   // truncates toward zero in C++
        }
    }
    return st.top();
}

