def eval_postfix(tokens: list) -> int:
    st = []
    for tk in tokens:
        if tk not in ("+", "-", "*", "/"):
            st.append(int(tk))
            continue
        b = st.pop()               # RIGHT operand pops FIRST
        a = st.pop()               # LEFT operand pops second
        if tk == "+":
            st.append(a + b)
        elif tk == "-":
            st.append(a - b)       # a - b, NOT b - a
        elif tk == "*":
            st.append(a * b)
        else:
            st.append(int(a / b))  # truncate toward ZERO, matching C++
    return st[0]
